solutionCode.python:
# Le temps du coureur 1, puis celui du coureur 2.
a, b = map(int, input().split())

# Le plus petit temps gagne.
if a < b:
    print(1)
elif b < a:
    print(2)
else:
    print("EGALITE")

solutionCode.cpp:
#include <iostream>
using namespace std;

int main() {
    int a, b;
    cin >> a >> b;
    // Le plus petit temps gagne.
    if (a < b) {
        cout << 1 << "\n";
    } else if (b < a) {
        cout << 2 << "\n";
    } else {
        cout << "EGALITE\n";
    }
    return 0;
}

